<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue';
import { RouterLink, useRoute, useRouter } from 'vue-router';
import { PhPlus, PhFloppyDisk, PhUserCircle, PhSquaresFour, PhBrain, PhShieldCheck, PhArrowClockwise } from '@phosphor-icons/vue';
import { AgentDefinitionSchema, AgentIdSchema, runtimeStateLabels, requiredRuntimeState, type RuntimeConfig, type PlatformType } from '../../../../packages/contracts/src/index';
import { AgentCapabilitiesSchema, type AgentCapability, type AgentCapabilities } from '../../../../packages/contracts/src/agent-workbench';
import { PluginIdSchema, pluginMetadata } from '../../../../packages/contracts/src/plugins';
import type { PersonaBinding } from '../../../../packages/contracts/src/management';
import { confirmDestructiveAction } from '../../composables/unsaved';
import { runtimeRequest } from '../../api/typescript';
import { randomId } from '../../utils/random-id';
import AgentPromptConfiguration from './AgentPromptConfiguration.vue';
import AgentTestPanel from './AgentTestPanel.vue';
import ContextPolicyEditor from './ContextPolicyEditor.vue';
import NamedBindingPicker from './NamedBindingPicker.vue';
import RuntimeStatePermissions from './RuntimeStatePermissions.vue';
import CommandPolicyDetails from './CommandPolicyDetails.vue';
import { agentWorkbenchTab, isGeneralModelTool, isPlatformCapability, capabilityBindingName, capabilityIsMounted, canMountCapability } from './agent-workbench-model';
import type { AgentWorkbenchBindingDraft, AgentWorkbenchSavePayload } from './AgentWorkbench.types';
const config = defineModel<RuntimeConfig>({ required: true });
const props = withDefaults(defineProps<{ publishedConfig: RuntimeConfig; extraToolOptions?: { id: string; label: string; detail: string }[]; busy?: boolean; savedBinding?: PersonaBinding; toolCatalogue?: AgentCapabilities }>(), { extraToolOptions: () => [], busy: false });
const emit = defineEmits<{ save: [payload: AgentWorkbenchSavePayload]; bindingDraft: [payload: AgentWorkbenchBindingDraft]; agentChanged: [id: string]; inspectRun: [id: string] }>();
const route = useRoute(); const router = useRouter();
const tab = computed(() => agentWorkbenchTab(route.query.section));
const tabs = [{ id: 'persona', label: '人设与模型', icon: PhUserCircle }, { id: 'tools', label: '工具与资料', icon: PhSquaresFour }, { id: 'context', label: '上下文与记忆', icon: PhBrain }, { id: 'permissions', label: '执行与审批', icon: PhShieldCheck }];
function chooseTab(id: string): void { void router.push({ path: route.path, query: { ...route.query, section: agentWorkbenchTab(id) } }); }
const agent = computed(() => typeof route.query.agent === 'string' ? config.value.agents.find(item => item.id === route.query.agent) : config.value.agents[0]);
const publishedAgent = computed(() => props.publishedConfig.agents.find(item => item.id === agent.value?.id));
const selectedBinding = ref<AgentWorkbenchBindingDraft>();
const promptEditor = ref<InstanceType<typeof AgentPromptConfiguration>>(); const localNotice = ref('');
const currentBinding = computed(() => selectedBinding.value?.agentId === agent.value?.id ? selectedBinding.value : undefined);
const agentDirty = computed(() => agent.value !== undefined && JSON.stringify(agent.value) !== JSON.stringify(publishedAgent.value));
const readyToSave = computed(() => currentBinding.value?.ready && (agentDirty.value || currentBinding.value.dirty));
const catalogue = ref<AgentCapabilities>({ entries: [], note: '' }); const catalogueBusy = ref(false); const catalogueError = ref(''); const toolQuery = ref(''); const extraToolName = ref('');
const effectiveCatalogue = computed(() => props.toolCatalogue ?? catalogue.value);
const sourceLabels: Record<AgentCapability['source'], string> = { builtin: '内置工具', search: '网络搜索', plugin: '插件', mcp: 'MCP', skills: 'Skills', native_extension: '原生扩展', platform: '平台能力' };
const platformGroups: { id: PlatformType; label: string }[] = [{ id: 'napcat', label: 'QQ / NapCat' }, { id: 'telegram', label: 'Telegram' }, { id: 'weixin', label: '微信' }];
function matches(entry: AgentCapability): boolean { const query = toolQuery.value.trim().toLocaleLowerCase(); return !query || `${entry.label} ${entry.description} ${entry.toolName ?? ''} ${entry.sourceId}`.toLocaleLowerCase().includes(query); }
type CapabilityView = 'general' | 'platform' | 'resources';
const capabilityView = ref<CapabilityView>('general');
const capabilityPlatform = ref<PlatformType>('napcat');
function choosePlatform(platform: PlatformType): void { capabilityPlatform.value = platform; capabilityView.value = 'platform'; }
function toolGroup(entry: AgentCapability): { id: string; label: string } {
  if (entry.source === 'builtin') {
    if (entry.requiredCapabilities.some(value => value === 'process.execute' || value === 'process.pty')) return { id: 'builtin:execution', label: '命令与进程' };
    if (entry.requiredCapabilities.some(value => value === 'memory.read' || value === 'memory.write')) return { id: 'builtin:memory', label: '长期记忆' };
    if (entry.requiredCapabilities.includes('knowledge.read')) return { id: 'builtin:knowledge', label: '知识检索' };
    if (entry.requiredCapabilities.some(value => value === 'files.read' || value === 'files.write')) return { id: 'builtin:files', label: '文件与技能' };
    if (entry.requiredCapabilities.includes('agent.delegate')) return { id: 'builtin:delegation', label: 'Agent 委派' };
    return { id: 'builtin:conversation', label: '会话与工具结果' };
  }
  const plugin = entry.source === 'plugin' ? PluginIdSchema.safeParse(entry.sourceId) : undefined;
  return { id: `${entry.source}:${entry.sourceId}`, label: plugin?.success ? pluginMetadata[plugin.data].name : sourceLabels[entry.source] };
}
const generalTools = computed(() => effectiveCatalogue.value.entries.filter(entry => isGeneralModelTool(entry) && matches(entry)));
function platformTools(platform: PlatformType): AgentCapability[] { return effectiveCatalogue.value.entries.filter(entry => isPlatformCapability(entry, platform) && matches(entry)); }
const groupedGeneralTools = computed(() => { const groups = new Map<string, { id: string; label: string; entries: AgentCapability[] }>(); for (const entry of generalTools.value) { const category = toolGroup(entry); const group = groups.get(category.id); if (group) group.entries.push(entry); else groups.set(category.id, { ...category, entries: [entry] }); } return [...groups.values()]; });
const selectedPlatformTools = computed(() => platformTools(capabilityPlatform.value));
const selectedPlatformName = computed(() => platformGroups.find(item => item.id === capabilityPlatform.value)?.label ?? '平台');
const nonModelPermissions = computed(() => effectiveCatalogue.value.entries.filter(entry => (entry.kind === 'command' || entry.kind === 'resource') && capabilityBindingName(entry) !== undefined && matches(entry)));
function mounted(entry: AgentCapability): boolean { return capabilityIsMounted(entry, agent.value?.resources.tools ?? []); }
function minimumState(entry: AgentCapability): string { return runtimeStateLabels[requiredRuntimeState(entry.requiredCapabilities)]; }
function availability(entry: AgentCapability): string { return entry.availability === 'not_implemented' ? '不支持' : entry.availability === 'disabled' ? '来源未启用' : entry.availability === 'runtime_discovery' ? '运行时发现' : entry.kind === 'command' ? (mounted(entry) ? '已装配指令' : '未装配指令') : entry.kind === 'platform_status' ? '平台状态' : mounted(entry) ? '已装配' : '未装配'; }
function toggleTool(entry: AgentCapability, event: Event): void { const value = agent.value; const name = capabilityBindingName(entry); if (!value || !name || !(event.target instanceof HTMLInputElement) || (!canMountCapability(entry) && event.target.checked)) return; if (event.target.checked) { if (!value.resources.tools.includes(name)) value.resources.tools.push(name); } else value.resources.tools = value.resources.tools.filter(item => item !== name); }
const unknownTools = computed(() => agent.value?.resources.tools.filter(name => !effectiveCatalogue.value.entries.some(entry => capabilityBindingName(entry) === name)) ?? []);
function removeTool(name: string): void { if (agent.value) agent.value.resources.tools = agent.value.resources.tools.filter(item => item !== name); }
function addTool(): void { const name = extraToolName.value.trim(); if (!agent.value || !name) return; if (!agent.value.resources.tools.includes(name)) agent.value.resources.tools.push(name); extraToolName.value = ''; }
async function refreshCatalogue(): Promise<void> { if (catalogueBusy.value) return; catalogueBusy.value = true; catalogueError.value = ''; try { catalogue.value = await runtimeRequest('agent-capabilities', AgentCapabilitiesSchema); } catch (cause) { catalogueError.value = cause instanceof Error ? `能力目录加载失败。${cause.message}` : '能力目录加载失败。请点击“刷新目录”重试。'; } finally { catalogueBusy.value = false; } }
async function chooseAgent(event: Event): Promise<void> { if (!(event.target instanceof HTMLSelectElement) || props.busy) return; const selector = event.target; const selected = agent.value?.id ?? ''; const failure = await router.push({ path: route.path, query: { ...route.query, agent: selector.value } }); if (failure) selector.value = selected; }
async function addAgent(): Promise<void> { if (props.busy) return; const item = AgentDefinitionSchema.parse({ id: `agent-${randomId().slice(0, 8)}`, displayName: '新 Agent', connectionId: config.value.connections[0]?.id ?? 'default' }); const failure = await router.push({ path: route.path, query: { ...route.query, agent: item.id, section: 'persona' } }); if (failure) return; config.value.agents.push(item); }
function bindingChanged(value: AgentWorkbenchBindingDraft): void { selectedBinding.value = value; emit('bindingDraft', value); }
function save(): void { const value = currentBinding.value; if (!value || !value.ready || props.busy) return; emit('save', { agentId: value.agentId, personaId: value.personaId, expectedBindingRevision: value.expectedBindingRevision }); }
async function discardCurrent(): Promise<void> {
  const current = agent.value; if (!current || props.busy) return;
  const published = publishedAgent.value;
  if (published) {
    if (!confirmDestructiveAction(`放弃“${current.displayName}”的未发布字段和人格选择？将恢复此 Agent 的已发布配置及已保存绑定。其他草稿和测试输入会保留。`)) return;
    const restored = AgentDefinitionSchema.parse(published);
    config.value.agents = config.value.agents.map(item => item.id === current.id ? restored : item);
    promptEditor.value?.resetBinding(); localNotice.value = '此 Agent 的字段和人格选择已恢复。其他草稿和测试输入已保留。'; return;
  }
  const next = config.value.agents.find(item => item.id !== current.id);
  if (!next) { localNotice.value = '当前草稿没有其他 Agent。请先添加一个 Agent，再放弃这次新建。'; return; }
  if (!confirmDestructiveAction(`放弃新建“${current.displayName}”？只移除此未发布 Agent。其他 Agent 和页面草稿会保留。未发送的测试消息会在离开前单独确认。`)) return;
  const failure = await router.push({ path: route.path, query: { ...route.query, agent: next.id } });
  if (failure) return;
  config.value.agents = config.value.agents.filter(item => item.id !== current.id);
  localNotice.value = '已放弃新建 Agent。其他 Agent 和页面草稿已保留。';
}
function setDirectories(event: Event): void { if (agent.value && event.target instanceof HTMLTextAreaElement) agent.value.resources.directories = event.target.value.split('\n').map(value => value.trim()).filter(Boolean); }
function setApprovalTools(event: Event): void { if (agent.value && event.target instanceof HTMLTextAreaElement) agent.value.approvalTools = event.target.value.split('\n').map(value => value.trim()).filter(Boolean); }
function setDelegates(event: Event): void { if (agent.value && event.target instanceof HTMLSelectElement) agent.value.delegationTargets = Array.from(event.target.selectedOptions).map(option => AgentIdSchema.parse(option.value)); }
function toggleExtraction(event: Event): void { if (!agent.value || !(event.target instanceof HTMLInputElement)) return; agent.value.memoryExtraction.enabled = event.target.checked; if (event.target.checked && !agent.value.memoryExtraction.libraryId) { const id = agent.value.resources.memoryLibraries[0]; if (id) agent.value.memoryExtraction.libraryId = id; } }
function extractionLibrary(event: Event): void { if (!agent.value || !(event.target instanceof HTMLSelectElement)) return; if (event.target.value) agent.value.memoryExtraction.libraryId = event.target.value; else delete agent.value.memoryExtraction.libraryId; }
watch(() => agent.value?.id, value => { localNotice.value = ''; if (value) emit('agentChanged', value); }, { immediate: true });
onMounted(() => { if (!props.toolCatalogue) void refreshCatalogue(); if (typeof route.query.agent !== 'string' && agent.value) void router.replace({ path: route.path, query: { ...route.query, agent: agent.value.id } }); });
</script>
<template>
  <section class="agent-workbench">
    <header class="agent-toolbar"><div class="agent-selector"><label for="active-agent">当前 Agent</label><select id="active-agent" :value="agent?.id ?? ''" :disabled="busy" @change="chooseAgent"><option v-if="!agent" value="" disabled>请选择已有 Agent</option><option v-for="item in config.agents" :key="item.id" :value="item.id">{{item.displayName}}{{item.enabled?'':' · 已停用'}}</option></select><button type="button" :disabled="busy" @click="addAgent"><PhPlus :size="17"/>新增</button><label v-if="agent" class="enabled-toggle"><input v-model="agent.enabled" type="checkbox" :disabled="busy">启用</label></div><div class="agent-actions"><span v-if="agent" role="status">{{agentDirty || currentBinding?.dirty?'有未发布修改':publishedAgent?'当前已发布':'新 Agent 草稿'}}</span><button v-if="agent" type="button" class="discard-button" :disabled="busy || (publishedAgent!==undefined && !agentDirty && !currentBinding?.dirty)" @click="discardCurrent">{{publishedAgent?'放弃修改':'放弃新建'}}</button><button type="button" class="publish-button" :disabled="busy || !readyToSave" @click="save"><PhFloppyDisk :size="17"/>{{busy?'处理中…':'发布此 Agent'}}</button></div></header>
    <p v-if="localNotice" class="publish-note" role="status">{{localNotice}}</p><p class="publish-note">发布会保存此 Agent 及人格选择。运行中和排队任务将中断，旧审批将失效。其他对象的草稿会保留。</p>
    <nav class="agent-tabs" aria-label="Agent 设置"><button v-for="item in tabs" :key="item.id" type="button" :aria-current="tab===item.id?'page':undefined" @click="chooseTab(item.id)"><component :is="item.icon" :size="18"/>{{item.label}}</button></nav>
    <p v-if="!agent" class="helper" role="status" style="padding:24px">找不到此 Agent。请选择已有 Agent，或新建 Agent。</p><div v-if="agent" class="agent-editor-grid">
      <fieldset class="agent-editor" :disabled="busy">
        <section v-show="tab==='persona'" class="editor-section agent-profile">
          <section class="profile-model"><div class="section-heading"><h2>模型</h2><RouterLink to="/providers">管理模型连接</RouterLink></div><div class="two-columns"><label>模型服务<select v-model="agent.connectionId"><option v-if="!config.connections.some(item=>item.id===agent?.connectionId)" :value="agent.connectionId">{{agent.connectionId}}（未登记）</option><option v-for="connection in config.connections" :key="connection.id" :value="connection.id">{{connection.id}} · {{connection.protocol==='responses'?'Responses':'Chat Completions'}}</option></select></label><label>模型名称<input v-model="agent.model" required placeholder="填写此服务支持的模型名称"></label></div><p class="helper">选择模型服务，再填写准确的模型名称。右侧可测试当前草稿。</p></section>
          <AgentPromptConfiguration ref="promptEditor" :key="agent.id" :model-value="agent" :persisted="publishedAgent!==undefined" binding-mode="workbench" :saved-binding="savedBinding" @update:model-value="Object.assign(agent,$event)" @binding-draft="bindingChanged"/>
          <details class="profile-identity"><summary>基本信息</summary><div class="two-columns"><label>Agent 名称<input v-model="agent.displayName" required></label><label>执行引擎<input value="OpenAI Agents SDK" readonly></label></div><p class="helper">Agent ID：{{agent.id}}。修改名称不会改变 ID。</p></details>
        </section>
        <section v-if="tab==='tools'" class="editor-section capability-editor">
          <div class="section-heading"><h2>工具与资料</h2><button type="button" :disabled="catalogueBusy" @click="refreshCatalogue"><PhArrowClockwise :size="16"/>刷新目录</button></div>
          <p class="helper">勾选能力后发布此 Agent。实际调用仍需通过人格、发送者权限和平台检查。</p>
          <nav class="capability-switch" aria-label="能力分类"><button type="button" :aria-pressed="capabilityView==='general'" @click="capabilityView='general'">通用能力</button><button type="button" :aria-pressed="capabilityView==='platform'" @click="capabilityView='platform'">平台专属能力</button><button type="button" :aria-pressed="capabilityView==='resources'" @click="capabilityView='resources'">资源与自动处理</button></nav>
          <div class="platform-shortcuts" aria-label="平台专属能力入口"><span>平台</span><button v-for="platform in platformGroups" :key="platform.id" type="button" :aria-pressed="capabilityView==='platform'&&capabilityPlatform===platform.id" @click="choosePlatform(platform.id)">{{platform.label}}</button></div>
          <label class="tool-search">查找能力<input v-model="toolQuery" type="search" placeholder="输入用途、工具名或来源"></label>
          <p v-if="catalogueError" class="error-message" role="alert">{{catalogueError}}</p><p v-if="catalogueBusy" class="helper" role="status">正在读取服务端能力目录…</p>
          <section v-if="capabilityView==='general'" class="tool-group">
            <p class="helper">{{generalTools.length}} 项匹配能力。展开分组以装配工具；默认展开已装配的分组。</p>
            <details v-for="group in groupedGeneralTools" :key="`${group.id}:${agent.id}`" class="capability-group" :open="!!toolQuery.trim() || group.entries.some(entry=>mounted(entry))"><summary><strong>{{group.label}}</strong><span>{{group.entries.filter(entry=>mounted(entry)).length}} / {{group.entries.length}} 已装配</span></summary>
              <article v-for="entry in group.entries" :key="entry.id" class="tool-row"><input v-if="entry.toolName" :checked="mounted(entry)" type="checkbox" :aria-label="`装配 ${entry.label}`" :disabled="entry.availability==='not_implemented'&&!mounted(entry)" @change="toggleTool(entry,$event)"><div><div class="tool-title"><strong>{{entry.label}}</strong><span class="tool-state" :class="{limited:entry.availability!=='registered'}">{{availability(entry)}}</span><span v-if="mounted(entry)&&entry.availability!=='registered'" class="tool-state">已装配</span></div><small>{{sourceLabels[entry.source]}} · {{entry.sessionTypes.map(value=>value==='group'?'群聊':'私聊').join('、')}}<template v-if="entry.platforms.length<3"> · {{entry.platforms.map(value=>value==='napcat'?'QQ / NapCat':value==='telegram'?'Telegram':'微信').join('、')}}</template></small><p v-if="entry.availability!=='not_implemented'" class="helper">最低运行态：{{minimumState(entry)}}。平台与使用条件仍需满足。</p><details class="tool-conditions"><summary>查看用途与条件</summary><p>{{entry.description}}</p><code v-if="entry.toolName">{{entry.toolName}}</code><ul><li v-for="condition in entry.requirements" :key="condition">{{condition}}</li></ul><RouterLink v-if="entry.settingsPath" :to="entry.settingsPath">配置来源</RouterLink></details></div></article>
            </details><p v-if="!generalTools.length&&!catalogueBusy" class="helper">没有匹配的通用能力。请修改搜索词，或查看其他分类。</p>
          </section>
          <section v-else-if="capabilityView==='platform'" class="tool-group"><div class="section-heading"><h3>{{selectedPlatformName}}</h3><span>{{config.platforms.some(item=>item.type===capabilityPlatform&&item.enabled)?'已配置平台':'尚未启用平台实例'}}</span></div><p class="helper">只适用于此平台。展开每项的使用条件，查看会话范围和平台要求。</p><article v-for="entry in selectedPlatformTools" :key="entry.id" class="tool-row"><input v-if="entry.kind==='tool'&&entry.toolName" :checked="mounted(entry)" type="checkbox" :aria-label="`装配 ${entry.label}`" :disabled="entry.availability==='not_implemented'&&!mounted(entry)" @change="toggleTool(entry,$event)"><div><div class="tool-title"><strong>{{entry.label}}</strong><span class="tool-state" :class="{limited:entry.availability!=='registered'}">{{availability(entry)}}</span><span v-if="mounted(entry)&&entry.availability!=='registered'" class="tool-state">已装配</span></div><small>{{entry.sessionTypes.map(value=>value==='group'?'群聊':'私聊').join('、')}} · {{sourceLabels[entry.source]}}{{entry.toolName?` · ${entry.toolName}`:''}}</small><p v-if="entry.kind==='platform_status'">{{entry.description}}</p><p v-if="entry.availability!=='not_implemented'" class="helper">最低运行态：{{minimumState(entry)}}。平台与使用条件仍需满足。</p><details class="tool-conditions"><summary>查看用途与条件</summary><p v-if="entry.kind!=='platform_status'">{{entry.description}}</p><ul><li v-for="condition in entry.requirements" :key="condition">{{condition}}</li></ul></details></div></article><p v-if="!selectedPlatformTools.length&&!catalogueBusy" class="helper">没有匹配的专属能力。请修改搜索词，或选择其他平台。</p></section>
          <section v-else class="resource-capabilities">
            <div class="section-heading"><h3>知识库、MCP 与 Skills</h3><RouterLink to="/extensions">管理资源</RouterLink></div>
            <NamedBindingPicker v-model="agent.resources.knowledgeLibraries" label="知识库" :options="config.knowledgeLibraries.map(item=>({id:item.id,label:item.displayName,detail:item.id}))"/><NamedBindingPicker v-model="agent.resources.mcpServers" label="MCP 服务" :options="config.mcpServers.map(item=>({id:item.id,label:item.id,detail:`${item.transport} · 连接后获取工具列表。调用仍需授权`}))"/><NamedBindingPicker v-model="agent.resources.skills" label="Skill 库" :options="config.skillLibraries.map(item=>({id:item.id,label:item.id,detail:item.directory}))"/>
            <details v-if="nonModelPermissions.length" class="capability-group" :open="!!toolQuery.trim() || nonModelPermissions.some(entry=>mounted(entry))"><summary><strong>指令与自动处理</strong><span>{{nonModelPermissions.filter(entry=>mounted(entry)).length}} / {{nonModelPermissions.length}} 已装配</span></summary><p class="helper">这些条目用于指令和自动处理的授权检查，不会作为工具交给模型。</p><article v-for="entry in nonModelPermissions" :key="entry.id" class="tool-row"><input :checked="mounted(entry)" type="checkbox" :aria-label="`装配 ${entry.label} 权限`" :disabled="!canMountCapability(entry)&&!mounted(entry)" @change="toggleTool(entry,$event)"><div><div class="tool-title"><strong>{{entry.label}}</strong><span class="tool-state">{{mounted(entry)?'已装配':'未装配'}}</span><span v-if="entry.availability!=='registered'" class="tool-state limited">{{availability(entry)}}</span></div><small>{{sourceLabels[entry.source]}} · {{capabilityBindingName(entry)}}</small><p v-if="entry.availability!=='not_implemented'" class="helper">最低运行态：{{minimumState(entry)}}。平台与使用条件仍需满足。</p><details class="tool-conditions"><summary>查看使用条件</summary><ul><li v-for="condition in entry.requirements" :key="condition">{{condition}}</li></ul></details></div></article></details>
            <details class="capability-group"><summary><strong>其他工具与未归类绑定</strong><span>{{unknownTools.length}} 项</span></summary><p class="helper">填写已接入工具的准确名称。未确认来源的绑定会保留，但不能据此判断可用性。</p><div v-for="name in unknownTools" :key="name" class="unknown-tool"><span>{{extraToolOptions.find(item=>item.id===name)?.label || name}}<small>{{name}} · 未确认来源</small></span><button type="button" @click="removeTool(name)">移除</button></div><div class="add-tool"><label>工具名称<input v-model="extraToolName" placeholder="填写已接入工具的准确名称"></label><button type="button" @click="addTool">装配工具</button></div></details>
          </section>
          <details class="catalogue-note"><summary>实际调用如何判断权限</summary><p class="helper">{{effectiveCatalogue.note}}</p></details>
        </section>
        <section v-if="tab==='context'" class="editor-section"><h2>上下文与记忆</h2><section class="editor-block"><h3>长期记忆</h3><NamedBindingPicker v-model="agent.resources.memoryLibraries" label="长期记忆库" :options="config.memoryLibraries.map(item=>({id:item.id,label:item.displayName,detail:item.id}))"/><label class="check-row"><input type="checkbox" :checked="agent.memoryExtraction.enabled" @change="toggleExtraction"><span>自动提取长期记忆<small>从私聊提取记忆。按会话和发送者隔离。</small></span></label><label v-if="agent.memoryExtraction.enabled">写入记忆库<select :value="agent.memoryExtraction.libraryId ?? ''" @change="extractionLibrary"><option value="">选择已装配的记忆库</option><option v-if="agent.memoryExtraction.libraryId&&!agent.resources.memoryLibraries.includes(agent.memoryExtraction.libraryId)" :value="agent.memoryExtraction.libraryId">{{agent.memoryExtraction.libraryId}}（未装配）</option><option v-for="library in config.memoryLibraries.filter(item=>agent?.resources.memoryLibraries.includes(item.id))" :key="library.id" :value="library.id">{{library.displayName}}</option></select></label><p class="helper">先选择记忆库，再开启自动提取。自动提取还需要对应工具和发送者写入权限。群聊不自动提取记忆。</p><RouterLink to="/memories">管理记忆内容与整理</RouterLink></section><section class="editor-block"><h3>历史上下文与压缩</h3><ContextPolicyEditor v-model="agent.contextPolicy" :connections="config.connections" :agent-model="agent.model"/></section></section>
        <section v-if="tab==='permissions'" class="editor-section"><h2>执行与审批</h2><p class="helper">发送者的运行态决定权限。此处只设置审批、执行环境和任务限制。</p><RouterLink to="/permissions">分配发送者运行态</RouterLink><details class="editor-block"><summary>查看可用命令与参数</summary><CommandPolicyDetails/></details><details class="editor-block"><summary>查看三种运行态的固定权限</summary><RuntimeStatePermissions/></details><section class="editor-block"><h3>模型工具审批</h3><label>权限不足时的回复<input v-model="agent.permissionDenied"></label><label>需要逐次审批的工具名称（每行一个）<textarea :value="agent.approvalTools.join('\n')" rows="3" @input="setApprovalTools"/></label><p class="helper">填写模型工具名称。调用前暂停，等待管理员批准。批准不能提升运行态。直接发送的聊天指令按各自权限规则执行。</p></section>
          <section class="editor-block"><h3>执行环境与目录</h3><label>执行环境<select v-model="agent.resources.executionEnvironment"><option value="none">不使用执行环境</option><option v-if="agent.resources.executionEnvironment!=='none'&&!config.executionEnvironments.some(item=>item.id===agent?.resources.executionEnvironment)" :value="agent.resources.executionEnvironment">{{agent.resources.executionEnvironment}}（未登记）</option><option v-for="environment in config.executionEnvironments" :key="environment.id" :value="environment.id">{{environment.id}} · {{environment.type==='sdk_docker'?'SDK Docker':environment.type==='docker'?'Docker':'本机'}}</option></select></label><label>允许访问的目录（每行一个）<textarea :value="agent.resources.directories.join('\n')" rows="3" @input="setDirectories"/></label><p class="helper">选择已配置的执行环境。普通和资深干员态的命令只在 Docker 或 SDK Docker 中执行。填写允许此 Agent 访问的工作目录，每行一个。下载还需要执行环境开启网络。</p><RouterLink :to="{path:'/execution',query:{section:'settings'}}">管理执行环境</RouterLink></section>
          <section class="editor-block"><h3>执行限制</h3><p class="helper">限制一次任务的模型轮数、时间和 Token 用量。超时单位为毫秒，1000 毫秒等于 1 秒。</p><div class="two-columns"><label>最大模型轮数<input v-model.number="agent.budget.maxTurns" type="number" min="1" max="100"></label><label>超时（毫秒）<input v-model.number="agent.budget.timeoutMs" type="number" min="100" max="3600000"></label><label>Token 限制方式<select v-model="agent.budget.tokenLimitMode"><option value="context">上下文、轮数与超时限制</option><option value="cumulative">累计预算，预留收尾空间</option></select></label><label>{{agent.budget.tokenLimitMode==='cumulative'?'整次任务 Token 预算':'单次输出预算上限'}}<input v-model.number="agent.budget.maxTokens" type="number" min="1" max="1000000"></label></div></section>
          <section class="editor-block"><h3>多 Agent 委派</h3><p class="helper">选择可接收委派的 Agent。深度限制连续委派层数，次数限制整次任务的委派总量。</p><div class="two-columns"><label>最大委派深度<input v-model.number="agent.budget.maxDelegationDepth" type="number" min="0" max="8"></label><label>最大委派次数<input v-model.number="agent.budget.maxDelegations" type="number" min="0" max="32"></label><label>并行子 Agent 上限<input v-model.number="agent.budget.maxConcurrentChildren" type="number" min="1" max="8"></label><label>可委派 Agent<select multiple :value="agent.delegationTargets" @change="setDelegates"><option v-for="target in config.agents.filter(item=>item.id!==agent?.id)" :key="target.id" :value="target.id">{{target.displayName}}</option><option v-for="id in agent.delegationTargets.filter(value=>!config.agents.some(item=>item.id===value))" :key="id" :value="id">{{id}}（未登记）</option></select></label></div></section>
        </section>
      </fieldset>
      <AgentTestPanel :key="agent.id" :config="config" :published-config="publishedConfig" :agent-id="agent.id" :persona-id="currentBinding?.personaId ?? null" :published-persona-id="currentBinding?.publishedPersonaId ?? null" :ready="currentBinding?.ready ?? false" :disabled="busy"/>
    </div>
  </section>
